const MANAGEMENT_LABELS={CONTINUE_MONITORING:"ติดตามต่อ",CULTURAL_MANAGEMENT:"จัดการเชิงเขตกรรม",MECHANICAL_MANAGEMENT:"จัดการเชิงกล",BIOLOGICAL_REVIEW:"ทบทวนทางเลือกชีวภาพ",EXPERT_REVIEW:"ต้องให้ผู้เชี่ยวชาญตรวจ",CHEMICAL_REVIEW:"ทบทวนการใช้สาร — ยังติดข้อกำกับ",NO_ACTION_CURRENTLY_JUSTIFIED:"ยังไม่ต้องลงมือในขณะนี้"};

export class GovernedSpaRuntime {
  constructor({workspace,llm,idProvider=()=>globalThis.crypto.randomUUID()}={}){this.workspace=workspace;this.llm=llm;this.idProvider=idProvider;this.identity=null;this.lifecycleState={authority:"SERVER",fields:[],seasons:[]};this.caseState=null;this.due=[];}
  async synchronize(){const [session,lifecycle]=await Promise.all([this.workspace.session(),this.workspace.lifecycle()]);this.identity=session.identity;this.lifecycleState=lifecycle;await this.refreshDue();return{identity:this.identity,lifecycle};}
  scopeFor(field){if(!field||field.authority_state==="LOCAL_DRAFT"||!this.lifecycleState.fields.some((item)=>item.field_id===field.field_id&&item.season_id===field.season_id))return null;return{field_id:field.field_id,season_id:field.season_id};}
  presentFields(localFields=[]){const authoritative=this.lifecycleState.fields.map((field)=>({...field,authority_state:"SERVER_CONFIRMED"})),known=new Set(authoritative.map((item)=>item.field_id));return authoritative.concat(localFields.filter((item)=>!known.has(item.field_id)).map((item)=>({...item,authority_state:"LOCAL_DRAFT"})));}
  async createField(input){const result=await this.workspace.createField(input);await this.synchronize();return{...result.field,authority_state:"SERVER_CONFIRMED"};}
  async startCase(field,purpose="การตรวจจาก Primary SPA"){const scope=this.scopeFor(field);if(!scope)throw new Error("แปลงนี้ยังเป็นข้อมูลร่างบนอุปกรณ์ บันทึกแปลงบนระบบก่อนเริ่มเคส");const created=await this.workspace.createInvestigationRecord("CASE",{...scope,purpose});this.caseState={scope:{...scope,case_id:created.record.case_id},conversation_id:null};await this.refreshCase();return this.caseState;}
  async captureStatement(text){if(!this.caseState?.scope)throw new Error("กรุณาเริ่มเคสที่บันทึกบนระบบก่อน");const result=await this.llm.chat({...this.caseState.scope,scope:"CASE_SCOPED",message:text});if(result.governed_response?.conversation_id)this.caseState.conversation_id=result.governed_response.conversation_id;await this.refreshCase();return result;}
  async refreshCase(){const scope=this.caseState?.scope;if(!scope)return null;const settled=await Promise.allSettled([this.workspace.getInvestigationBundle(scope),this.workspace.getInvestigationAssessment(scope),this.workspace.getGuidance(scope),this.workspace.getManagementOptions(scope),this.workspace.getDecisionActionOutcomeContext(scope),this.workspace.getFollowUpReminderContext(scope),this.workspace.getAuthoritativeTimeline(scope),this.workspace.getVisualEvidenceBundle(scope)]);const value=(index,fallback)=>settled[index].status==="fulfilled"?settled[index].value:fallback;Object.assign(this.caseState,{bundle:value(0,{observations:[],evidence:[]}),assessment:value(1,null),guidance:value(2,{guidance:null}),management:value(3,{all_option_evaluations:[]}),decision:value(4,{decisions:[],actions:[],outcomes:[]}),followUp:value(5,{plans:[],reminders:[]}),timeline:value(6,{events:[]}),visual:value(7,{images:[]}),degraded:settled.map((item,index)=>item.status==="rejected"?index:null).filter((item)=>item!=null)});return this.caseState;}
  async uploadPhoto(file,options={}){if(!this.caseState?.scope)throw new Error("กรุณาเริ่มเคสก่อนแนบภาพ");const observation=this.caseState.bundle?.observations?.at(-1),uploaded=await this.workspace.uploadVisualEvidence(file,this.caseState.scope,{observation_id:observation?.observation_id??null,guidance_id:this.caseState.guidance?.guidance?.guidance_id??null,...options});await this.refreshCase();return uploaded;}
  async manualPhotoReview(imageEvidenceId,{target="VISIBLE_FEATURE",state="UNKNOWN",basis="รอผู้ใช้หรือผู้ตรวจทบทวนภาพ",appropriate_view=false}={}){const result=await this.workspace.assessVisualEvidence(imageEvidenceId,{quality:{FOCUS:"UNKNOWN",EXPOSURE:"UNKNOWN"},observability:[{target,state,basis,appropriate_view}],features:[],assessment_method:"EXPLICIT_STRUCTURED_INPUT",assessment_version:"primary-spa-manual/v1"});await this.refreshCase();return result;}
  managementOptions(){return(this.caseState?.management?.all_option_evaluations??this.caseState?.management?.options??[]).map((option)=>({...option,label:MANAGEMENT_LABELS[option.option_class]??option.title??option.option_class,selectable:["ELIGIBLE","eligible"].includes(option.eligibility_state)}));}
  async selectManagementOption(option,rawText="ผู้ใช้ยืนยันทางเลือกนี้"){if(!option?.management_option_id)throw new Error("กรุณาเลือกทางเลือกที่ระบบเปิดให้พิจารณา");const review=this.caseState.management,scope=this.caseState.scope,type=option.option_class==="CONTINUE_MONITORING"?"CONTINUE_MONITORING":option.option_class==="NO_ACTION_CURRENTLY_JUSTIFIED"?"NO_ACTION_CURRENTLY":"SELECT_MANAGEMENT_OPTION",history=this.caseState.decision?.decisions??[],current=history.at(-1)??null;const decision=await this.workspace.createHumanDecision({request_id:`spa-decision-${this.idProvider()}`,...scope,management_review_id:review.management_review_id,decision_type:type,selected_option_id:option.management_option_id,selection_source:"AUTHENTICATED_UI",selection_raw_text:rawText,selection_source_span:{start:0,end:rawText.length,text:rawText},explicit_confirmation:true,expected_current_decision_id:current?.decision_id??null,supersedes_decision_id:current?.decision_id??null});await this.refreshCase();return decision;}
  async refreshDue(){const results=await Promise.allSettled(this.lifecycleState.fields.map((field)=>this.workspace.getDueReminders({field_id:field.field_id,season_id:field.season_id})));this.due=results.flatMap((item)=>item.status==="fulfilled"?(item.value.due??[]):[]);return this.due;}
  async localPatterns(){const value=await this.workspace.getLocalPatternCandidates();return(value.candidates??[]).map((candidate)=>({...candidate,bounded_message:"มีเคสที่ข้อมูลบางส่วนเข้ากันได้ แต่ยังเรียกว่าเป็นการระบาดไม่ได้"}));}
  async nominateCase(rawDescription="เก็บเคสนี้ไว้เป็นความรู้"){const scope=this.caseState?.scope;if(!scope)throw new Error("กรุณาเปิดเคสก่อน");const response=await this.workspace.createLearningNomination({request_id:`spa-learning-${this.idProvider()}`,type:"KNOWLEDGE_GAP",source_type:"FIELD_CASE",field_id:scope.field_id,season_id:scope.season_id,case_id:scope.case_id,raw_description:rawDescription,structured_gap:{gap_code:"FIELD_CASE_REVIEW_NOMINATED"},proposed_scope:"bounded field case",supporting_refs:[scope.case_id],privacy_state:"REVIEW_REQUIRED",consent_or_usage_rights_state:"REVIEW_REQUIRED"}),nomination=response.nomination??response;return{...nomination,friendly_message:"เก็บเป็น Learning Candidate ไว้แล้วครับ ยังไม่เปลี่ยนความรู้หลักจนกว่าจะผ่านการตรวจ"};}
}

export function casePresentation(state){const assessment=state?.assessment,guidance=state?.guidance?.guidance??state?.guidance,visual=state?.visual?.images??[];return{known:(state?.bundle?.observations??[]).map((item)=>item.note).filter(Boolean),missing:assessment?.missing_evidence??assessment?.evidence_gaps??[],next_action:guidance?.how_to_inspect??guidance?.why_now??"บันทึกสิ่งที่เห็นตามจริงหรือแนบภาพเมื่อช่วยแยกข้อมูลได้",visual:visual.map((image)=>({id:image.image_evidence_id,level:image.ve_level,quality:image.quality_assessments?.at(-1)?.quality??null,observability:image.quality_assessments?.at(-1)?.observability??[],boundary:"ภาพที่รับแล้วไม่เท่ากับภาพที่วิเคราะห์ และไม่ใช่การวินิจฉัย"})),question_limit_per_turn:1,initial_question_limit:2};}
